import { spawnSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';
const EXE = '/workspace/dataset/test11_executable';

const PREFIX = Buffer.from("{'name': ");
const SUFFIX = Buffer.from(", 'age': 5}");

// Parse a repr body (bytes between the outer quotes) into one token per code point.
function parseTokens(body, quote) {
  const toks = [];
  let i = 0;
  while (i < body.length) {
    const b = body[i];
    if (b === 0x5c) { // backslash
      const c = String.fromCharCode(body[i + 1]);
      if (c === 'x') { toks.push({ k: 'hex2', cp: parseInt(body.slice(i+2,i+4).toString(), 16), raw: body.slice(i,i+4).toString() }); i += 4; }
      else if (c === 'u') { toks.push({ k: 'hex4', cp: parseInt(body.slice(i+2,i+6).toString(), 16), raw: body.slice(i,i+6).toString() }); i += 6; }
      else if (c === 'U') { toks.push({ k: 'hex8', cp: parseInt(body.slice(i+2,i+10).toString(), 16), raw: body.slice(i,i+10).toString() }); i += 10; }
      else if (c === 'n') { toks.push({ k: 'short', cp: 10, raw: '\\n' }); i += 2; }
      else if (c === 'r') { toks.push({ k: 'short', cp: 13, raw: '\\r' }); i += 2; }
      else if (c === 't') { toks.push({ k: 'short', cp: 9, raw: '\\t' }); i += 2; }
      else if (c === '\\') { toks.push({ k: 'short', cp: 92, raw: '\\\\' }); i += 2; }
      else if (c === "'") { toks.push({ k: 'short', cp: 39, raw: "\\'" }); i += 2; }
      else if (c === '"') { toks.push({ k: 'short', cp: 34, raw: '\\"' }); i += 2; }
      else { toks.push({ k: 'UNKNOWN', raw: body.slice(i, i+4).toString() }); i += 2; }
    } else {
      // decode one UTF-8 sequence
      let n = b < 0x80 ? 1 : b < 0xe0 ? 2 : b < 0xf0 ? 3 : 4;
      const s = body.slice(i, i + n).toString('utf8');
      toks.push({ k: 'lit', cp: s.codePointAt(0) });
      i += n;
    }
  }
  return toks;
}

export function runChunk(cps) {
  const a = cps.map(c => String.fromCodePoint(c)).join('');
  const r = spawnSync(EXE, ['--a', a, '--b', '5'], { maxBuffer: 1 << 29 });
  if (r.status !== 0) throw new Error('exit ' + r.status + ': ' + r.stderr.toString().slice(0, 400));
  const nl = cps.filter(c => c === 10).length;
  const lines = [];
  { // split stdout buffer on 0x0a
    let start = 0;
    for (let i = 0; i < r.stdout.length; i++) if (r.stdout[i] === 0x0a) { lines.push(r.stdout.slice(start, i)); start = i + 1; }
    lines.push(r.stdout.slice(start));
  }
  const line = lines[4 + nl];
  if (!line.slice(0, PREFIX.length).equals(PREFIX)) throw new Error('bad prefix: ' + line.slice(0,40).toString());
  if (!line.slice(line.length - SUFFIX.length).equals(SUFFIX)) throw new Error('bad suffix: ' + line.slice(-40).toString());
  const quoted = line.slice(PREFIX.length, line.length - SUFFIX.length);
  const quote = String.fromCharCode(quoted[0]);
  if (quoted[quoted.length-1] !== quoted[0]) throw new Error('quote mismatch');
  const toks = parseTokens(quoted.slice(1, quoted.length - 1), quote);
  if (toks.length !== cps.length) throw new Error('token count ' + toks.length + ' != ' + cps.length);
  return { quote, toks };
}
